    },
    {
      "claim": "Bacampicillin hydrochloride, another acyloxyalkyl ester beta-lactam prodrug, has adequate aqueous solubility of 3 mg/mL at pH 7.5 and 154 mg/mL at pH 1.2, supporting prodrug ester solubility for oral absorption.",
      "card_ids": ["C48"]
    }
  ],
